// Entry mode: A 8-bit (mf=1), X 16-bit (xf=0), DB=$7E, DP=0
//
// Physical/elemental damage formula: base attack -> random variance ->
// elemental multiplier -> creature-type multiplier -> critical bonus ->
// defense subtraction (clamped to 0) -> final multiply/divide -> clamp to
// [1, 9999]. Result left in $A4:$A5.
//
// FIX (2026-07-06): calc_dmg_emu (the delegation helper every caller of
// this routine used) was a genuine no-op weak stub -- the entire damage
// formula below never ran, so whatever raw pre-formula value already sat
// in $A4:$A5 was used as-is: no random variance dampening, no defense
// mitigation, no 9999 cap. Root-caused from a player bug report ("a
// hedgehog deals 120 damage this early in the game") reproduced on
// ff4-port/fixtures/012-first-worldmap-combat.lss. See MemPalace
// wing=ff4-gnw room=obstacles-and-solutions for the full investigation.
//
// PITFALL 9 (hidden upper byte B): several steps below do an 8-bit `LDA`
// (touches only the low byte of the accumulator, leaving whatever
// "hidden" high byte -- B -- was there from earlier 16-bit-A operations)
// immediately followed by a `TAX`/`TAY` (which transfers the FULL 16-bit
// C register, B included, not just the low byte). `LDA $38FC` right
// before the final multiply is this pitfall's own historical example
// (pitfalls.yaml #9: a prior, incomplete translation attempt of this
// exact routine produced a saturated 9999 instead of the correct
// unsaturated value because it silently zero-extended instead of
// preserving B). Every such LDA below is written as
// `cpu->a = (cpu->a & 0xFF00) | ram[addr]` (preserve B) and every such
// TAX/TAY as `cpu->x = cpu->a` (propagate the full width) -- never a
// plain `(uint16_t)ram[addr]` zero-extension.

// "apply damage multiplier" ($03:CA41): multiplier is encoded as 2x the
// real factor (0=immune, 1=half damage, 2=normal, 4=double, ...) -- see
// the BNE/LSR/BNE dispatch below, which is a literal translation of that
// encoding, not a re-derived formula.
static void calc_dmg_apply_mult(Snes *snes) {
    uint8_t *ram = snes->ram;
    Cpu *cpu = snes->cpu;
    uint8_t mult = (uint8_t)(cpu->a & 0xFF);   // BNE tests this 8-bit value
    if (mult == 0) {
        write16(ram, 0xA4, 0);
        return;
    }
    uint8_t shifted = (uint8_t)(mult >> 1);      // LSR (8-bit, B untouched)
    cpu->a = (uint16_t)((cpu->a & 0xFF00) | shifted);
    if (shifted != 0) {
        cpu->x = cpu->a;                          // TAX (full width)
        write16(ram, 0x393D, cpu->x);
        uint16_t a4a5 = read16(ram, 0xA4);
        cpu->x = a4a5;                             // LDX $A4
        write16(ram, 0x393F, a4a5);
        Mult16_c(snes);                             // JSR $83B9
        write16(ram, 0xA4, read16(ram, 0x3941));
    } else {
        // multiplier was exactly 1 (halved to 0): halve the running
        // 16-bit total by one bit (LSR $A5 / ROR $A4 as a single 16-bit
        // shift-right of the A5:A4 pair).
        uint16_t a4a5 = read16(ram, 0xA4);
        a4a5 = (uint16_t)(a4a5 >> 1);
        write16(ram, 0xA4, a4a5);
    }
}

void CalcDmg_c(Snes *snes) {
    uint8_t *ram = snes->ram;
    Cpu *cpu = snes->cpu;

    // $C99F-C9AB: base attack, halved (clamped to $FF if the halved high
    // byte is nonzero) as the upper bound for the random-variance roll.
    uint16_t base_attack = read16(ram, 0x3902);
    write16(ram, 0x3956, base_attack);
    write16(ram, 0x3958, base_attack);
    uint16_t halved = (uint16_t)(base_attack >> 1);
    write16(ram, 0x3956, halved);
    if ((halved >> 8) != 0) {
        write16(ram, 0x3956, 0x00FF);
    }

    // $C9B9-C9C2: TDC/TAX clears A (and hidden B) to 0; RandXA(X=0,
    // A=ram[$3956]) rolls the variance; TAX/STX $3956 stores the full
    // 16-bit result (RandXA_c's own C body always zero-extends its
    // uint8_t result into cpu->a, so B is 0 here in practice, but read it
    // via cpu->a rather than assume that to stay correct if that ever
    // changes).
    cpu->a = 0;                                  // TDC
    cpu->x = 0;                                  // TAX
    cpu->a = (uint16_t)((cpu->a & 0xFF00) | ram[0x3956]); // LDA $3956
    RandXA_emu(snes);                             // JSR $8379
    cpu->x = cpu->a;                              // TAX (full width)
    write16(ram, 0x3956, cpu->x);                 // STX $3956

    // $C9C5: Add16 -- $395A = $3956 (variance) + $3958 (base_attack)
    Add16_c(snes);
    write16(ram, 0xA4, read16(ram, 0x395A));      // LDX $395A / STX $A4

    // $C9CD-C9D6: elemental multiplier, then creature-type multiplier
    cpu->a = (uint16_t)((cpu->a & 0xFF00) | ram[0x38FE]); // LDA $38FE
    calc_dmg_apply_mult(snes);                     // JSR $CA41
    cpu->a = (uint16_t)((cpu->a & 0xFF00) | ram[0x38FF]); // LDA $38FF
    calc_dmg_apply_mult(snes);                     // JSR $CA41

    // $C9D9-C9EA: critical-hit bonus (8-bit ADC into $A4 with carry into $A5)
    cpu->a = (uint16_t)((cpu->a & 0xFF00) | ram[0x3900]); // LDA $3900
    if ((cpu->a & 0xFF) != 0) {
        uint16_t sum = (uint16_t)((uint16_t)ram[0xA4] + (uint16_t)ram[0x3901]);
        ram[0xA4] = (uint8_t)(sum & 0xFF);
        uint8_t carry = (sum > 0xFF) ? 1 : 0;
        ram[0xA5] = (uint8_t)(ram[0xA5] + carry);
    }

    // $C9EC-CA01: subtract defense (16-bit, equivalent to the asm's
    // byte-by-byte SBC-with-borrow), clamp negative to 0.
    uint16_t dmg = read16(ram, 0xA4);
    uint16_t defense = read16(ram, 0x3904);
    dmg = (dmg < defense) ? 0 : (uint16_t)(dmg - defense);
    write16(ram, 0xA4, dmg);

    // $CA01-CA0D: multiply the (possibly-zero-clamped) result by
    // ram[$38FC] via Mult16.
    write16(ram, 0x393D, dmg);                      // LDX $A4 / STX $393D
    cpu->a = (uint16_t)((cpu->a & 0xFF00) | ram[0x38FC]); // LDA $38FC (Pitfall 9's own example line)
    cpu->x = cpu->a;                                // TAX (full width)
    write16(ram, 0x393F, cpu->x);                   // STX $393F
    Mult16_c(snes);                                  // JSR $83B9

    // $CA10-CA1E: saturate the low word to $FFFF if the high word overflowed
    if (read16(ram, 0x3943) != 0) {
        write16(ram, 0x3941, 0xFFFF);
    }
    write16(ram, 0x3945, read16(ram, 0x3941));

    // $CA21-CA28: divide by ram[$3906]
    cpu->a = (uint16_t)((cpu->a & 0xFF00) | ram[0x3906]); // LDA $3906
    cpu->x = cpu->a;                                // TAX (full width)
    write16(ram, 0x3947, cpu->x);                   // STX $3947
    Div16_c(snes);                                   // JSR $8407

    // $CA2B-CA3E: clamp to 9999, force a minimum of 1
    uint16_t final_dmg = read16(ram, 0x3949);
    if (final_dmg > 9999) final_dmg = 9999;
    if (final_dmg == 0) final_dmg = 1;
    write16(ram, 0xA4, final_dmg);
}


