// asm wrapper from the contract
// ---------------------------------------------------------------------------

static void run_asm(Snes *snes, uint16_t arg_a) {
    Cpu *c = snes->cpu;
    c->dp = 0x0000;
    c->db = 0x7E;
    c->mf = true;
    c->xf = false;
    c->a = 0; c->x = 0; c->y = 0;
    c->a = arg_a;
    c->z = (arg_a == 0);
    c->n = ((arg_a & 0x8000) != 0);
    run_emulated_func(snes, TARGET_ADDR_24);
}

// ---------------------------------------------------------------------------
// Host PRNG
// ---------------------------------------------------------------------------

static uint32_t host_rng_state = 0xC0FFEEu;
static uint32_t host_rng(void) {
    uint32_t x = host_rng_state;
    x ^= x << 13; x ^= x >> 17; x ^= x << 5;
    host_rng_state = x; return x;
}

// ---------------------------------------------------------------------------
// Trial driver
// ---------------------------------------------------------------------------

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <rom.sfc> [n_trials]\n", argv[0]);
        return 1;
    }
    int n_trials = (argc >= 3) ? atoi(argv[2]) : 1000;

    size_t rom_len = 0;
    uint8_t *rom = read_file(argv[1], &rom_len);
    if (!rom) return 2;

    Snes *snes = snes_init();
    if (!snes_loadRom(snes, rom, rom_len)) { fprintf(stderr, "loadRom fail\n"); return 3; }
    snes_reset(snes, true);
    for (int i = 0; i < 60; i++) snes_runFrame(snes);
    snes->cpu->i = true; snes->cpu->nmiWanted = false; snes->cpu->irqWanted = false;

    Snap baseline;
    snap_take(&baseline, snes);

    fprintf(stderr, "CalcDmg asm vs C : %d trials\n", n_trials);

    int fails = 0;
    for (int trial = 0; trial < n_trials; trial++) {
        snap_restore(&baseline, snes);

        // Randomise inputs.
        snes->ram[0x3900] = (uint8_t)host_rng();
        snes->ram[0x3901] = (uint8_t)host_rng();
        write16(snes->ram, 0x3902, (uint16_t)host_rng());
        write16(snes->ram, 0x3904, (uint16_t)host_rng());
        snes->ram[0x3905] = (uint8_t)host_rng();
        uint16_t arg_a = (uint16_t)host_rng();

        // Pre-call snapshot for replaying C with the exact same state.
        Snap pre;
        snap_take(&pre, snes);

        // Run ASM
        run_asm(snes, arg_a);
        uint16_t out_asm = read16(snes->ram, 0x00A4);

        // Restore and run C
        snap_restore(&pre, snes);
        snes->cpu->dp = 0x0000;
        snes->cpu->db = 0x7E;
        snes->cpu->mf = true;
        snes->cpu->xf = false;
        snes->cpu->a = 0; snes->cpu->x = 0; snes->cpu->y = 0;
        snes->cpu->a = arg_a;
        CalcDmg_c(snes);
        uint16_t out_c = read16(snes->ram, 0x00A4);

        bool ok = (out_asm == out_c);
        if (!ok) {
            printf("trial %4d : asm=%u c=%u  FAIL\n", trial, out_asm, out_c);
            fails++;
        }
    }

    printf("\n=== summary === trials: %d, fails: %d\n", n_trials, fails);
    free(rom);
    return fails == 0 ? 0 : 1;
}
